INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('101', '101-mcq-grammar', 'Grammar', 'Grammar MCQ', 'mcq_grammar', 10, 'For each question from 1 to 10, choose the answer that best fits. Shade your answer (1, 2, 3 or 4) on the OAS.', '{"questions": {"1": {"stem_plain": "Dummy 1 grammer mcq, any option is ok _____.", "options": {"1": "option1", "2": "option2", "3": "option3", "4": "option4"}}}, "answers": {"1": {"note": "\u201cdespite\u201d \u662f\u4ecb\u8bcd\uff0c\u540e\u9762\u63a5\u540d\u8bcd\u6216\u52a8\u540d\u8bcd\u77ed\u8bed\uff08being tired\uff09\uff1b\u800c \u201calthough\u201d \u662f\u8fde\u8bcd\uff0c\u540e\u9762\u5fc5\u987b\u63a5\u5b8c\u6574\u7684\u53e5\u5b50\u3002", "concept": "\u8ba9\u6b65\u4ecb\u8bcd\u4e0e\u8fde\u8bcd\u7684\u533a\u5206 \u2014 Concession \u2014 despite vs although", "zh": "\u5c3d\u7ba1\u5f88\u7d2f\uff0c\u7537\u5b69\u4eec\u8fd8\u662f\u7ee7\u7eed\u7740\u6e38\u620f\u3002", "answer": "2"}}}');
INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('102', '102-mcq-vocab', 'Vocab', 'Vocabulary MCQ', 'mcq_vocab', 5, 'For each question from 11 to 15, choose the answer that best fits. Shade your answer (1, 2, 3 or 4) on the OAS.', '{"questions": {"11": {"stem_plain": "Dummy 1 vocabulary item: She felt ________ after the long hike.", "options": {"1": "Option 1", "2": "Option 2", "3": "Option 3", "4": "Option 4"}}}, "passages": {}, "answers": {"11": {"zh": "\u5bf9stem_plain\u7684\u4e2d\u6587\u7ffb\u8bd1", "note": "\u5bf9\u6b63\u786eoption \u7684\u89e3\u91ca", "concept": "\u9898\u578b\u6982\u5ff5-Concept", "answer": "1", "choices": [{"opt": "1", "word": "Option 1", "zh": "\u9009\u98791", "eg": "The recruits were told to **Option 1** at the parade square before the inspection."}, {"opt": "2", "word": "Option 2", "zh": "\u9009\u98792", "eg": "Sales of the toy **Option 2** sharply after reports of a safety defect."}, {"opt": "3", "word": "Option 3", "zh": "\u9009\u98793", "eg": "Several branches **Option 3** onto the road during last night''s thunderstorm."}, {"opt": "4", "word": "Option 4", "zh": "\u9009\u98794", "eg": "The plans for the rebuilding of the orphanage **Option 4** as there was no donor for the project."}]}}}');
INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('103', '103-cloze-vocab', 'V.Cloze', 'Vocabulary Cloze', 'mcq_vocab_cloze', 5, 'For each question from 16 to 20, choose the word closest in meaning to the underlined word(s). Shade your answer (1, 2, 3 or 4) on the OAS.', '{"questions": {"16": {"stem_plain": "sample", "marks": 1, "interaction": "mcq_vocab_cloze", "options": {"1": "Option 1", "2": "Option 2", "3": "Option 3", "4": "Option 4"}}}, "passages": {"cloze": ["This is a [Q16(prototype)] paragraph for vocabulary cloze."], "zh": ["\u8fd9\u662f\u8bcd\u6c47\u586b\u7a7a\u793a\u4f8b\u6bb5\u843d\u3002"]}, "answers": {"16": {"note": "\u56fa\u5b9a\u642d\u914d \u2014 replace stems, passages, and teaching copy when content is ready.", "answer": "(TBD)", "choices": [{"opt": "1", "word": "Option 1", "zh": "\u9009\u98791", "eg": "An example sentence with the Option1"}, {"opt": "2", "word": "Option 2", "zh": "", "eg": "An example sentence with the Option2"}, {"opt": "3", "word": "Option 3", "zh": "", "eg": ""}, {"opt": "4", "word": "Option 4", "zh": "", "eg": ""}]}}}');
INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('104', '104-mcq-visual', 'Visual', 'Visual Text', 'mcq_visual', 5, 'Study the visual text and answer questions 21 to 25. Shade your answer (1, 2, 3 or 4) on the OAS.', '{"questions": {"21": {"stem_plain": "According to the visual text, the main purpose is to ________.", "marks": 1, "interaction": "mcq_visual", "options": {"1": "Option 1", "2": "Option 2", "3": "Option 3", "4": "Option 4"}}}, "passages": {}, "answers": {"21": {"note": "\u89e3\u91ca\u4e3a\u4ec0\u4e48\u9009\u8fd9\u4e2a\u7b54\u6848 \u2014 replace stems, passages, and teaching copy when content is ready.", "concept": "\u4e3b\u65e8\u9898\u578b", "answer": "1"}}}');
INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('105', '105-cloze-grammar', 'G.Cloze', 'Grammar Cloze', 'cloze', 10, 'Choose the most suitable word from the word bank for each blank (26–35).', '{"questions": {"29": {"stem_plain": "", "marks": 1, "interaction": "cloze"}}, "passages": {"bank": {"A": "after", "B": "before", "C": "during", "D": "since"}, "cloze": ["This is a [Q29] paragraph for grammar cloze."], "zh": ["这是词汇填空示例段落。"]}, "answers": {"29": {"concept": "语法题", "note": "中文解释为什么选这个答案。", "answer": "A"}}}');
INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('106', '106-editing', 'Editing', 'Editing', 'cloze', 10, 'Each underlined word has a spelling or grammatical error. Write the correct word in the box.', '{"questions": {"51": {"stem_plain": "", "marks": 1, "interaction": "cloze"}}, "passages": {"cloze": ["Prototype editing cloze: The sun lend me a [Q46(hend)] when I am down."], "zh": ["示例完形填空段落。"]}, "answers": {"46": {"concept": "固定习惯搭配", "note": "完美契合经典口语及书面语习语 lend a hand，表示在需要时“伸出援手”或“搭把手”提供帮助。", "answer": "hand"}}}');
INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('107', '107-cloze-comprehension', 'C.Cloze', 'Comprehension Cloze', 'cloze', 15, 'Fill in each blank with the most suitable word.', '{"questions": {"51": {"stem_plain": "", "marks": 1, "interaction": "cloze"}}, "passages": {"cloze": ["Prototype comprehension cloze: The sun lend me a [Q46(hend)] when I am down."], "zh": ["\u793a\u4f8b\u5b8c\u5f62\u586b\u7a7a\u6bb5\u843d\u3002"]}, "answers": {"46": {"concept": "\u56fa\u5b9a\u4e60\u60ef\u642d\u914d", "note": "\u5b8c\u7f8e\u5951\u5408\u7ecf\u5178\u53e3\u8bed\u53ca\u4e66\u9762\u8bed\u4e60\u8bed lend a hand\uff0c\u8868\u793a\u5728\u9700\u8981\u65f6\u201c\u4f38\u51fa\u63f4\u624b\u201d\u6216\u201c\u642d\u628a\u624b\u201d\u63d0\u4f9b\u5e2e\u52a9\u3002", "answer": "hand"}}}');
INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('108', '108-synthesis', 'Synth', 'Synthesis & Transformation', 'synthesis', 10, 'Rewrite each sentence using the word(s) provided. Your answer must be in one sentence.', '{"questions": {"66": {"stem_plain": "Prototype synthesis cue.", "marks": 2, "interaction": "synthesis", "cue": "It was raining. We stayed indoors. (so)"}}, "answers": {"62": {"concept": "\u865a\u62df\u8bed\u6c14 \u2014 Conditional \u2192 Prepositional phrase (''Without + N'')", "zh": "\u6ca1\u6709\u6559\u7ec3\u7684\u9f13\u52b1\uff0c\u6211\u4eec\u672c\u4f1a\u5728\u534a\u9014\u653e\u5f03\u3002", "note": "\u6761\u4ef6\u6539\u5199\uff1a If the coach had not encouraged \u2026Without the coach''s encouragement\uff1b\u4e3b\u53e5 would have given up halfway \u4e0d\u53d8\u3002", "answer": "Without the coach''s encouragement, we would have given up halfway."}}}');
INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('109', '109-comprehension-open-ended', 'Open', 'Comprehension Open-Ended', 'blank_lines', 20, 'Read the passage and answer questions 71 to 75.', '{"passages": {"lines": ["line1", "line2"], "paragraphs": {"1": "\u7b2c\u4e00\u6bb5\u4ece\u7b2c1\u884c\u5f00\u59cb\uff0c\u7b2c\u4e00\u6bb5\u7684\u7ffb\u8bd1\u3002", "10": "\u7b2c\u4e8c\u6bb5\u4ece\u7b2c10\u884c\u5f00\u59cb\uff0c\u7b2c\u4e8c\u6bb5\u7684\u7ffb\u8bd1\u3002"}}, "questions": {"71": {"stem_plain": "Why did the writer feel happy? (1 mark)", "marks": 1, "interaction": "open_ended"}}, "answers": {"71": {"concept": "Prototype", "note": "Prototype paper \u2014 replace stems, passages, and teaching copy when content is ready.</em></p>", "answer": "(TBD)", "type": "comprehension"}}}');
INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('110', '110-writing-situational', 'S.Writing', 'Situational Writing', 'writing', 15, 'In your writing, include the key information as requested.', '{"questions": {"image": "swriting.jpeg", "task": ["Imagine you are Rama.", "**Write an email to the teacher-in-charge of the morning assembly, Mr Lim, for permission to make an announcement.**", "You are to refer to the picture and information on page 2 for your email."], "info": ["the purpose of Amazing Hearts 2024", "two reasons why you want to make the announcement", "two things that a student needs to do before donating a food item at the booth", "why you are asking Mr Lim to practise with you"], "interaction": "writing"}, "answers": {"sample": ["Dear Mr Lim,", "I am writing to **request permission** to make an announcement at the morning assembly"], "markdown": ["\u8fd9\u4e2a\u5173\u4e8e\u201cAmazing Hearts 2024\u201d\u7684\u7533\u8bf7\u90ae\u4ef6\u662f\u4e00\u7bc7\u5b8c\u7f8e\u7684\u5b98\u65b9\u6ee1\u5206\u8303\u6587\uff08PSLE \u5b9e\u7528\u6587\u4f53 AL1 \u6c34\u51c6\uff09\u3002\u4e3b\u8981\u4eae\u70b9\u5982\u4e0b\uff1a", "### 1. \u4efb\u52a1\u5168\u9762\u8fbe\u6807 (Complete Task Fulfillment)\n", "### 2. \u8bed\u6c14\u4e0e\u8bcd\u6c47\u6781\u5176\u5f97\u4f53 (Polite Tone & Formal Vocabulary)\n*", "### 3. \u903b\u8f91\u8854\u63a5\u6781\u5176\u4e25\u5bc6 (Excellent Sentence Transitions)\n"]}}');
INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('111', '111-writing-continuous', 'C.Writing', 'Continuous Writing', 'writing', 40, 'Write a composition of at least 150 words.', '{"questions": {"image": "cwriting.jpeg", "interaction": "writing"}, "answers": {"sample": ["Dear Mr Lim,", "I am writing to **request permission** to make an announcement at the morning assembly"], "markdown": ["\u8fd9\u4e2a\u5173\u4e8e\u201cAmazing Hearts 2024\u201d\u7684\u7533\u8bf7\u90ae\u4ef6\u662f\u4e00\u7bc7\u5b8c\u7f8e\u7684\u5b98\u65b9\u6ee1\u5206\u8303\u6587\uff08PSLE \u5b9e\u7528\u6587\u4f53 AL1 \u6c34\u51c6\uff09\u3002\u4e3b\u8981\u4eae\u70b9\u5982\u4e0b\uff1a", "### 1. \u4efb\u52a1\u5168\u9762\u8fbe\u6807 (Complete Task Fulfillment)\n", "### 2. \u8bed\u6c14\u4e0e\u8bcd\u6c47\u6781\u5176\u5f97\u4f53 (Polite Tone & Formal Vocabulary)\n*", "### 3. \u903b\u8f91\u8854\u63a5\u6781\u5176\u4e25\u5bc6 (Excellent Sentence Transitions)\n"]}}');
INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('201', '201-mcq-applications', '语文应用', '语文应用', 'mcq', 10, '从第1题到第25题，每题提供4个选项，其中只有一个是正确的。选出代表正确答案的数字（1, 2, 3或4），然后把电脑作答卷上相应的空心椭圆涂满。', '{"questions": {"1": {"stem_plain": "\u8fd9\u662f\u5916\u5a46\u4eb2\u624b\u7ed9\u6211\u505a\u7684\u88ab\u5b50\uff0c\u6211\u4f1a**\u52a0\u500d**\u73cd\u60dc\u3002", "marks": 2, "options": {"1": "ji\u00e1 b\u0113i", "2": "ji\u0101 b\u00e8i", "3": "ji\u00e1 p\u0113i", "4": "ji\u0101 p\u00e8i"}}}, "answers": {"1": {"answer": "2"}}}');
INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('202', '202-cloze', '填空', '短文填空', 'mcq', 10, '根据短文的内容和上下文的意思，从括号中选出适当的词语。', '{"questions": {"16": {"stem_plain": "", "marks": 2, "options": {"1": "\u7231\u62a4", "2": "\u4e89\u53d6", "3": "\u4fdd\u536b", "4": "\u5b9e\u73b0"}}}, "passages": {"cloze": ["\u6211\u548c\u5f1f\u5f1f\u90fd\u5f88\u559c\u6b22\u5c0f\u52a8\u7269\uff0c\u4e00\u76f4\u60f3\u517b\u53ea\u5c0f\u5154\u5b50\u3002"]}, "answers": {"16": {"answer": "4"}}}');
INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('203', '203-reading-one', '阅读一', '阅读一', 'mcq', 10, '根据短文的内容和上下文的意思，选出适当的答案。', '{"questions": {"21": {"stem_plain": "\u4e3a\u4ec0\u4e48\u4f5c\u8005\u548c\u5f1f\u5f1f\u4f1a\u62a5\u540d\u53c2\u52a0\u52a8\u7269\u6536\u5bb9\u4e2d\u5fc3\u7684\u8bfe\u7a0b\uff1f", "marks": 2, "options": {"1": "\u4ed6\u4eec\u60f3\u8981\u53bb\u90a3\u91cc\u9886\u517b\u4e24\u53ea\u5c0f\u5154\u5b50\u3002", "2": "\u4ed6\u4eec\u60f3\u5728\u90a3\u91cc\u8ba4\u8bc6\u66f4\u591a\u7684\u5c0f\u670b\u53cb\u3002", "3": "\u5988\u5988\u5e0c\u671b\u4ed6\u4eec\u901a\u8fc7\u8bfe\u7a0b\u5b66\u4f1a\u7167\u987e\u5c0f\u52a8\u7269\u3002", "4": "\u8001\u5e08\u8981\u6c42\u4ed6\u4eec\u53bb\u5b66\u4e60\u4e0d\u540c\u52a8\u7269\u7684\u751f\u6d3b\u4e60\u60ef\u3002"}}}, "passages": {"cloze": ["\u661f\u671f\u516d\u65e9\u4e0a\uff0c\u6211\u548c\u5f1f\u5f1f\u65e9\u65e9\u5c31\u8d77\u5e8a\u4e86\u3002"]}, "answers": {"21": {"answer": "2"}}}');
INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('204', '204-dialogue', '对话', '对话', 'mcq', 8, '根据上下文的意思，从表中选出最适当的短语或短句，然后把代表它们的数字填写在作答簿上相应的格子里。', '{"questions": {"26": {"marks": 2, "interaction": "mcq"}}, "passages": {"cloze": ["\u4e3d\u4e91\uff1a \u6211\u4e70\u5f97\u592a\u591a\u4e86\uff0c\u521a\u5403\u5b8c\u4e91\u541e\u9762\uff0c\u8fd9\u4e2a\u8089\u5305\u5b50\u597d\u5927\uff0c [Q26] \u3002", "\u7f8e\u82f1\uff1a \u4e3a\u4ec0\u4e48\u4e0d\u53ef\u4ee5\u5462\uff1f\u8981\u662f\u4f60\u518d\u7ee7\u7eed\u5403\uff0c [Q27] \uff0c\u90a3\u4e0d\u662f\u66f4\u7cdf\u5417\uff1f"], "bank": {"1": "\u98df\u7269\u662f\u5f88\u5b9d\u8d35\u7684", "2": "\u5dee\u70b9\u513f\u5c31\u5410\u51fa\u6765"}}, "answers": {"26": {"answer": "4"}}}');
INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('205', '205-reading-two-a', '阅读二A', '阅读二A', 'blank_lines', 10, '根据短文的内容和上下文的意思，回答问题，然后把答案填写在作答簿上。', '{"questions": {"30": {"stem_plain": "\u5b66\u6821\u4e3e\u529e\u8fd9\u9879\u6d3b\u52a8\u7684\u4e3b\u8981\u76ee\u7684\u662f\u4ec0\u4e48\uff1f", "marks": 2, "interaction": "mcq", "options": {"1": "\u628a\u5b66\u751f\u7684\u65e7\u4e66\u6350\u8d60\u7ed9\u56fd\u5bb6\u56fe\u4e66\u9986\u3002", "2": "\u914d\u5408\u56fd\u5bb6\u56fe\u4e66\u9986\u4e3b\u529e\u7684\u6350\u8d60\u6d3b\u52a8\u3002", "3": "\u8bad\u7ec3\u5b66\u751f\u6574\u7406\u56fd\u5bb6\u56fe\u4e66\u9986\u7684\u65e7\u4e66\u3002", "4": "\u8ba9\u56fd\u5bb6\u56fe\u4e66\u9986\u7684\u65e7\u4e66\u80fd\u91cd\u590d\u4f7f\u7528\u3002"}}}, "passages": {"image": "reading2a.jpeg"}, "answers": {"30": {"answer": "2"}}}');
INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('206', '206-reading-two-b', '阅读二B', '阅读二B', 'blank_lines', 22, '根据短文的内容和上下文的意思，回答问题，然后把答案填写在作答簿上。', '{"questions": {"34": {"stem_plain": "\u6587\u4e2d\u8868\u793a\u201c\u4e0d\u63a5\u53d7\u201d\u7684\u8bcd\u8bed\u662f________\u3002", "marks": 2, "interaction": "open_ended"}}, "passages": {"paragraphs": ["\u6211\u62ac\u8d77\u5934\uff0c\u770b\u89c1\u4e00\u4e2a\u773c\u775b\u5927\u5927\u7684\u5c0f\u7537\u5b69\u7ad9\u5728\u82b1\u5e97\u95e8\u53e3\u3002"]}, "answers": {"34": {"answer": "\u62d2\u7edd", "note": "\u89c1\u7b2c\u4e94\u6bb5\u6700\u540e\u7b2c\u4e8c\u53e5\u3002"}}}');
INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('301', '301-cloze_a', '短文选择', '短文选择', 'mcq', 10, '从第1题到第25题，每题提供4个选项，其中只有一个是正确的。选出代表正确答案的数字（1, 2, 3或4），规则见前所述。', '{"questions": {"1": {"marks": 2}}, "passages": {"cloze": ["\u201c\u963f\u59e8\uff0c\u6211\u8981\u8ba2\u82b1\u3002\u201d\u6211\u62ac\u8d77\u5934\uff0c\u770b\u89c1\u4e00\u4e2a\u773c\u775b[Q1]\u5c0f\u7537\u5b69\u7ad9\u5728\u82b1\u5e97\u95e8\u53e3\u3002"], "bank": {"1": "\u5927\u5927\u7684", "2": "\u5c0f\u5c0f\u7684", "3": "\u4e2d\u7b49\u5927\u5c0f\u7684", "4": "\u975e\u5e38\u5927\u7684"}}, "answers": {"1": {"answer": "2"}}}');
INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('302', '302-editing', '改错', '改错', 'inline_edit', 10, '从第1题到第25题，每题提供4个选项，其中只有一个是正确的。选出代表正确答案的数字（1, 2, 3或4），然后把电脑作答卷上相应的空心椭圆涂满。', '{"questions": {"6": {"marks": 2}}, "passages": {"cloze": ["\u201c\u963f\u59e8\uff0c\u6211\u8981\u8ba2\u82b1\u3002\u201d\u6211\u62ac\u8d77\u5934\uff0c\u770b\u89c1\u4e00\u4e2a[Q6(YY)]\u773c\u775b\u5927\u5927\u7684\u5c0f\u7537\u5b69\u7ad9\u5728\u82b1\u5e97\u95e8\u53e3\u3002"]}, "answers": {"6": {"answer": "XX"}}}');
INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('303', '303-reading-one', '短文填空', '短文填空', 'blank_lines', 10, '根据短文的内容和上下文的意思，选出适当的答案。', '{"questions": {"12": {"stem_plain": "\u6587\u4e2d\u8868\u793a\u201c\u4e0d\u63a5\u53d7\u201d\u7684\u8bcd\u8bed\u662f________\u3002", "marks": 2, "interaction": "open_ended"}}, "passages": {"cloze": ["\u201c\u963f\u59e8\uff0c\u6211\u8981\u8ba2\u82b1\u3002\u201d\u6211\u62ac\u8d77\u5934\uff0c\u770b\u89c1\u4e00\u4e2a\u773c\u775b\u5927\u5927\u7684\u5c0f\u7537\u5b69\u7ad9\u5728\u82b1\u5e97\u95e8\u53e3\u3002"]}, "answers": {"12": {"answer": "\u62d2\u7edd", "note": "\u89c1\u7b2c\u4e94\u6bb5\u6700\u540e\u7b2c\u4e8c\u53e5\u3002"}}}');
INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('304', '304-reading-two', '短文简答题', '短文简答题', 'blank_lines', 10, '根据短文的内容和上下文的意思，回答问题，然后把答案填写在作答簿上。', '{"questions": {"12": {"stem_plain": "\u6587\u4e2d\u8868\u793a\u201c\u4e0d\u63a5\u53d7\u201d\u7684\u8bcd\u8bed\u662f________\u3002", "marks": 2, "interaction": "open_ended"}}, "passages": {"cloze": ["\u201c\u963f\u59e8\uff0c\u6211\u8981\u8ba2\u82b1\u3002\u201d\u6211\u62ac\u8d77\u5934\uff0c\u770b\u89c1\u4e00\u4e2a\u773c\u775b\u5927\u5927\u7684\u5c0f\u7537\u5b69\u7ad9\u5728\u82b1\u5e97\u95e8\u53e3\u3002"]}, "answers": {"12": {"answer": "\u62d2\u7edd", "note": "\u89c1\u7b2c\u4e94\u6bb5\u6700\u540e\u7b2c\u4e8c\u53e5\u3002"}}}');
INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('305', '305-writing-one', '情境写作', '情境写作', 'writing', 40, '根据以下的话题和情境写作。', '{"questions": {"title": "\u5927\u5bb6\u5e94\u8be5\u4e00\u8d77\u505a\u51b3\u5b9a", "situation": ["\u4f60\u548c\u540c\u5b66\u4e00\u8d77\u505a\u5c0f\u7ec4\u4f5c\u4e1a, \u4ea4\u4f5c\u4e1a\u7684\u65e5\u671f\u5feb\u5230\u4e86, \u53ef\u662f\u7ec4\u957f\u5374\u51e0\u5929\u6ca1\u6765\u4e0a\u8bfe\u3002\u4f60\u6ca1\u5f97\u5230\u5927\u5bb6\u7684\u540c\u610f, \u5c31\u81ea\u5df1\u51b3\u5b9a\u5f53\u7ec4\u957f, \u8fd9\u8ba9\u5176\u4ed6\u7ec4\u5458\u5f88\u4e0d\u9ad8\u5174\u3002\u8fd9\u4ef6\u4e8b\u8ba9\u4f60\u4e0a\u4e86\u5b9d\u8d35\u7684\u4e00\u8bfe\u3002"], "interaction": "writing"}, "answers": {"sample": ["\u4e0a\u8bfe\u94c3\u58f0\u54cd\u8d77\uff0c\u53c8\u662f\u4e0a\u534e\u6587\u8bfe\u7684\u65f6\u95f4\u3002\u60f3\u5230\u4eca\u5929\u8981\u5199\u4f5c\u6587\uff0c\u73ed\u4e0a\u7684\u540c\u5b66\u90fd\u63d0\u4e0d\u8d77\u52b2\u3002", "\u5c06\u56fe\u7247\u4e2d\u7684\u5b8c\u6574\u6587\u7ae0\u5185\u5bb9\u63d0\u53d6\uff0c\u5e76\u4e25\u683c\u6309\u7167 PSLE \u6700\u9ad8\u8bc4\u7ea7 AL1\uff08\u7279\u4f18\uff09 \u7684\u6807\u51c6\u8fdb\u884c\u6df1\u5ea6\u5256\u6790\u3001\u9ad8\u4eae\u9ad8\u534e\u6210\u8bed/\u4e60\u8bed\u540e\u7684\u7ed3\u6784\u5316\u5b57\u5178\u683c\u5f0f"], "markdown": ["### 1. \u5ba1\u9898\u7acb\u610f\u4e0e\u60c5\u8282\u7ed3\u6784 (Impeccable Plot Consistency & Life Lesson)\n", "### 2. \u65f6\u5e8f\u8fc7\u6e21\u4e0e\u8282\u594f\u638c\u63a7 (Flawless Chronological Cohesion)\n", "### 3. \u8bcd\u6c47\u8001\u7ec3\u4e0e\u5fc3\u7406/\u795e\u6001\u63cf\u5199 (Sophisticated Vocabulary & Vivid Expressions)\n\u3002"]}}');
INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('306', '306-writing-two', '开头写作', '开头写作', 'writing', 40, '根据以下的话题和情境写作。', '{"answers": {"sample": ["\u4e00\u5929\uff0c\u6211\u653e\u5b66\u56de\u5230\u5bb6\uff0c\u53d1\u73b0\u95e8\u53e3\u653e\u7740\u4e00\u4e2a\u6f02\u4eae\u7684\u5c0f\u76d2\u5b50\uff0c\u4e0a\u9762\u6709\u6211\u7684\u540d\u5b57\u3002\u6211\u5174\u594b\u5730\u6253\u5f00\u76d2\u5b50\uff0c\u91cc\u9762\u53ea\u6709\u4e00\u5f20\u7eb8\uff0c\u5199\u7740\u201c\u606d\u559c\u4f60\uff01\u201d\u4e09\u4e2a\u5b57\u3002\u8fd9\u662f\u8c01\u7ed9\u6211\u7684\u5462\uff1f\u6211\u8010\u4e0d\u4f4f\u597d\u5947\u5fc3\uff0c\u4e00\u8fb9\u60f3\u7740\uff0c\u4e00\u8fb9\u628a\u90a3\u5f20\u201c\u606d\u559c\u4f60\u201d\u7684\u7eb8\u62ff\u8d77\u6765\u3002\u6211\u628a\u7eb8\u7ffb\u8fc7\u6765\u4e00\u770b\uff0c\u4e0a\u9762\u7adf\u7136\u8fd8\u6709\u4e00\u5c0f\u6bb5\u6587\u5b57\u4ee5\u53ca\u4e00\u4e2a\u4e8c\u7ef4\u7801\u3002"], "markdown": ["### 1. \u5ba1\u9898\u7acb\u610f\u4e0e\u6838\u5fc3\u4e3b\u9898 (Impeccable Theme Alignment & Modern Relevance)", "### 2. \u60c5\u8282\u4f0f\u7b14\u4e0e\u903b\u8f91\u95ed\u73af (Flawless Plot Consistency & Resolution)\n", "### 3. \u8bcd\u6c47\u8868\u8fbe\u4e0e\u4fee\u8f9e\u624b\u6cd5 (Sophisticated Vocabulary & Vivid Expressions)"]}, "questions": {"header": ["\u4e00\u5929\uff0c\u6211\u653e\u5b66\u56de\u5230\u5bb6\uff0c\u53d1\u73b0\u95e8\u53e3\u653e\u7740\u4e00\u4e2a\u6f02\u4eae\u7684\u5c0f\u76d2\u5b50\uff0c\u4e0a\u9762\u6709\u6211\u7684\u540d\u5b57\u3002\u6211\u5174\u594b\u5730\u6253\u5f00\u76d2\u5b50\uff0c\u91cc\u9762\u53ea\u6709\u4e00\u5f20\u7eb8\uff0c\u5199\u7740\u2018\u606d\u559c\u4f60\uff01\u2019\u4e09\u4e2a\u5b57\u3002\u8fd9\u662f\u8c01\u7ed9\u6211\u7684\u5462\uff1f\u6211\u2026\u2026"], "interaction": "writing"}}');
INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('401', '401-mcq', 'MCQ', 'MCQ', 'mcq', 40, '根据以下的话题和情境写作。', '{"questions": {"1": {"stem_plain": "Round 21 345 to the nearest thousand.", "marks": 1, "interaction": "mcq", "options": {"1": "20 000", "2": "21 000", "3": "21 300", "4": "22 000"}}}, "answers": {"1": {"answer": "2"}}}');
