INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('207', '207-topic-writing', '命题作文', '命题作文', 'writing', 30, '', '{"questions": {"title": "xxxx", "task": ["the purpose of Amazing Hearts 2024", "two reasons why you want to make the announcement", "two things that a student needs to do before donating a food item at the booth", "why you are asking Mr Lim to practise with you"], "interaction": "writing"}, "answers": {"sample": ["Dear Mr Lim,", "I am writing to **request permission** to make an announcement at the morning assembly"], "markdown": ["这个关于“Amazing Hearts 2024”的申请邮件是一篇完美的官方满分范文（PSLE 实用文体 AL1 水准）。主要亮点如下：", "### 1. 任务全面达标 (Complete Task Fulfillment)\n", "### 2. 语气与词汇极其得体 (Polite Tone & Formal Vocabulary)\n*", "### 3. 逻辑衔接极其严密 (Excellent Sentence Transitions)\n"]}}');
INSERT OR REPLACE INTO sections (section_id, stem, label, title, interaction, marks, instruction, template) VALUES ('208', '208-picture-writing', '看图作文', '看图作文', 'writing', 22, '', '{"questions": {"image": "swriting.jpeg", "bank": ["the purpose of Amazing Hearts 2024", "two reasons why you want to make the announcement", "two things that a student needs to do before donating a food item at the booth", "why you are asking Mr Lim to practise with you"], "interaction": "writing"}, "answers": {"sample": ["Dear Mr Lim,", "I am writing to **request permission** to make an announcement at the morning assembly"], "markdown": ["这个关于“Amazing Hearts 2024”的申请邮件是一篇完美的官方满分范文（PSLE 实用文体 AL1 水准）。主要亮点如下：", "### 1. 任务全面达标 (Complete Task Fulfillment)\n", "### 2. 语气与词汇极其得体 (Polite Tone & Formal Vocabulary)\n*", "### 3. 逻辑衔接极其严密 (Excellent Sentence Transitions)\n"]}}');
